import { test, expect } from '@playwright/test';

test('첫 화면이 뜨고 핵심 버튼이 보인다', async ({ page }) => {
  const errors = [];
  page.on('console', m => m.type() === 'error' && errors.push(m.text()));
  page.on('pageerror', e => errors.push(e.message));  // 안에서 터지는 것 수집

  await page.goto('/');
  await expect(page.getByRole('button', { name: '시작' })).toBeVisible();  // 핵심 버튼
  expect(errors, '콘솔/페이지 오류가 없어야').toEqual([]);  // 보이는데 터지는 것 차단
});
// 이 한 개가 앱이 아예 안 뜸 + 보이는데 안에서 죽음을 잡는다

// 잘 안 깨지는 순서 (위가 견고)
getByRole('button', { name: '저장' })  // ① 역할+이름. 접근성과 같이 좋아짐
getByLabel('이메일')                    // ② 라벨
getByText('저장됨')                     // ② 텍스트
getByTestId('save-btn')                 // ③ 테스트 전용 속성(명시적 계약)
page.locator('.panel > .btn:nth-child(2)') // ④ CSS 위치. 가장 잘 깨짐

// 왜? 역할, 라벨 = 사용자가 인식하는 것 (디자인 바뀌어도 유지)
//     CSS 위치 = 구현 세부 (클래스, 구조 바뀌면 깨짐)

// 시각 회귀. 기준 이미지와 비교
await expect(page).toHaveScreenshot('home.png', { maxDiffPixelRatio: 0.05 });
//   기준 저장 → 다음 실행과 픽셀 비교 → 차이가 허용치 넘으면 빨강
//   주의: 폰트, OS, GPU 다르면 미세 차이 → CI 와 같은 환경(도커)에서 기준 생성

// 실패 진단. 실패 시에만 스크린샷, 비디오, 추적 저장 (playwright.config)
use: {
  screenshot: 'only-on-failure',
  video: 'retain-on-failure',
  trace: 'retain-on-failure',   // 실패를 그대로 재생 (조작, 네트워크, DOM)
}
// 로그로 상상하는 대신 실패를 재생 → 디버깅 시간 몇 배 단축
